<?php require_once __DIR__.'/config/database.php';$pageTitle='সদস্য Registration';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$father=trim($_POST['father_name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$occupation=trim($_POST['occupation']??'');if($name!==''&&$phone!==''){$st=$pdo->prepare('INSERT INTO members(name,father_name,phone,email,address,occupation) VALUES(?,?,?,?,?,?)');$st->execute([$name,$father,$phone,$email,$address,$occupation]);$success='আপনার সদস্য আবেদন গ্রহণ করা হয়েছে। Admin অনুমোদনের পর যোগাযোগ করা হবে।';}}include __DIR__.'/includes/header.php';?><section class="section"><div class="container form-container"><div class="section-heading center"><span>Member Registration</span><h2>সদস্য Registration</h2></div><?php if($success):?><div class="success"><?=htmlspecialchars($success)?></div><?php endif;?><form method="post" class="public-form"><input name="name" placeholder="পূর্ণ নাম" required><input name="father_name" placeholder="পিতা/অভিভাবকের নাম"><input name="phone" placeholder="মোবাইল নাম্বার" required><input type="email" name="email" placeholder="ইমেইল"><input name="occupation" placeholder="পেশা"><textarea name="address" placeholder="পূর্ণ ঠিকানা"></textarea><button>Registration Submit করুন</button></form></div></section><?php include __DIR__.'/includes/footer.php';?>